                col = max(float3(maskA*MASK_VIS, maskB*MASK_VIS+0.1, max(maskA*MASK_VIS*2.0, maskB*MASK_VIS)+0.12)*fade, col);

}
            fragColor = float4(col*4.0,1.0);
            float4 gradmap;
